  brush.fillBleed(0.6); // 60% bleed
  brush.beginShape(0.5); // soft curve
  brush.vertex(0, 0); // top left
  brush.vertex(400, 0); // top right
  brush.vertex(400, 100); // bottom right
  brush.vertex(0, 100); // bottom left
